      ex: [
        mc('G8', 'reagieren auf → die Reaktion auf', I.choose, 'Der Körper reagiert auf den Reiz. → die Reaktion des Körpers …', ['auf den Reiz', 'den Reiz', 'des Reizes'],
          ['The body reacts to the stimulus. → the body’s reaction to the stimulus', 'Тело реагирует на раздражитель. → реакция тела на раздражитель', 'Тіло реагує на подразник. → реакція тіла на подразник', 'Beden uyarana tepki verir. → bedenin uyarana tepkisi'], { h: 'praep' }),
        mc('G8', 'von + Dativ ohne Artikel', I.choose, 'Man bewältigt Stress. → die Bewältigung …', ['von Stress', 'Stress', 'den Stress'],
          ['People cope with stress. → coping with stress', 'Человек справляется со стрессом. → преодоление стресса', 'Людина долає стрес. → подолання стресу', 'İnsan stresle başa çıkar. → stresle başa çıkma'], { h: 'von' }),
        mc('G8', 'die Angst vor', I.choose, 'Viele Menschen fürchten sich vor Veränderungen. → die Angst vieler Menschen …', ['vor Veränderungen', 'für Veränderungen', 'der Veränderungen'],
          ['Many people are afraid of change. → many people’s fear of change', 'Многие люди боятся перемен. → страх многих людей перед переменами', 'Багато людей боїться змін. → страх багатьох людей перед змінами', 'Birçok insan değişimden korkar. → birçok insanın değişim korkusu'], { h: 'praep' }),
        mc('G8', 'beeinflussen → der Einfluss auf', I.choose, 'Die Eltern beeinflussen das Verhalten des Kindes. → der Einfluss der Eltern …', ['auf das Verhalten des Kindes', 'das Verhalten des Kindes', 'an dem Verhalten des Kindes'],
          ['The parents influence the child’s behaviour. → the parents’ influence on the child’s behaviour', 'Родители влияют на поведение ребёнка. → влияние родителей на поведение ребёнка', 'Батьки впливають на поведінку дитини. → вплив батьків на поведінку дитини', 'Anne baba çocuğun davranışını etkiler. → anne babanın çocuğun davranışı üzerindeki etkisi'], { h: 'praep' }),
        mc('G8', 'Handelnder → durch', I.choose, 'Die Teilnehmenden nehmen die Farben unterschiedlich wahr. → die unterschiedliche Wahrnehmung der Farben …', ['durch die Teilnehmenden', 'von die Teilnehmenden', 'der Teilnehmenden durch'],
          ['The participants perceive the colours differently. → the differing perception of the colours by the participants', 'Участники по-разному воспринимают цвета. → различное восприятие цветов участниками', 'Учасники по-різному сприймають кольори. → різне сприйняття кольорів учасниками', 'Katılımcılar renkleri farklı algılıyor. → renklerin katılımcılar tarafından farklı algılanması'], { h: 'durch' }),
        mc('G8', 'umgehen mit → der Umgang mit', I.choose, 'Er geht gelassen mit Kritik um. → sein gelassener Umgang …', ['mit Kritik', 'von Kritik', 'der Kritik'],
          ['He deals calmly with criticism. → his calm way of dealing with criticism', 'Он спокойно относится к критике. → его спокойное отношение к критике', 'Він спокійно ставиться до критики. → його спокійне ставлення до критики', 'Eleştiriyi sakin karşılar. → eleştiri karşısındaki sakin tutumu'], { h: 'praep' }),
        mc('G8', 'Ergänzung nicht unverändert anhängen', I.choose, 'Welche Nominalgruppe ist richtig?', ['die Abhängigkeit des Kindes von den Eltern', 'die Abhängigkeit das Kind von den Eltern', 'die Abhängigkeit des Kindes die Eltern'],
          ['Which noun group is correct?', 'Какая именная группа правильная?', 'Яка іменна група правильна?', 'Hangi isim öbeği doğru?'], { h: 'praep' }),
        mc('G8', 'das Bedürfnis nach', I.prep, 'Jeder Mensch hat das Bedürfnis … Anerkennung.', ['nach', 'auf', 'für'],
          ['Every human being has a need for recognition.', 'У каждого человека есть потребность в признании.', 'Кожна людина має потребу у визнанні.', 'Her insanın takdir edilme ihtiyacı vardır.'], { h: 'praep' }),
        gap('G8', 'das Interesse an', I.prep, 'Die Studierenden interessieren sich für das Thema. → das Interesse der Studierenden ', ' dem Thema', 'an', ['für', 'auf'],
          ['The students are interested in the topic. → the students’ interest in the topic', 'Студенты интересуются темой. → интерес студентов к теме', 'Студенти цікавляться темою. → інтерес студентів до теми', 'Öğrenciler konuyla ilgileniyor. → öğrencilerin konuya ilgisi'], 'an / für / auf', { h: 'praep' }),
        gap('G8', 'Akkusativobjekt → Genitiv', I.article, 'Man verdrängt das Problem. → die Verdrängung ', ' Problems', 'des', ['dem', 'das'],
          ['People repress the problem. → the repression of the problem', 'Проблему вытесняют. → вытеснение проблемы', 'Проблему витісняють. → витіснення проблеми', 'Sorun bastırılır. → sorunun bastırılması'], 'des / dem / das', { h: 'genitiv' }),
      ],
